import React, { useEffect, useState, useRef } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useAuth } from '../lib/AuthContext'
import {
  getOrCreateConversation,
  getMessages,
  sendMessage,
  editMessage,
  deleteMessage,
  subscribeToMessages,
  unsubscribeFromMessages
} from '../lib/messages'

export default function ChatScreen() {
  const { contactUsername } = useParams()
  const { session, canSend } = useAuth()
  const navigate = useNavigate()

  const [conversation, setConversation] = useState(null)
  const [messages, setMessages] = useState([])
  const [input, setInput] = useState('')
  const [recording, setRecording] = useState(false)
  const [editingId, setEditingId] = useState(null)
  const [editContent, setEditContent] = useState('')
  const messagesEndRef = useRef(null)
  const channelRef = useRef(null)

  useEffect(() => {
    async function init() {
      const convo = await getOrCreateConversation({
        clientId: session.client.id,
        userId: session.user.id,
        contactUsername
      })
      setConversation(convo)
      const msgs = await getMessages(convo.id)
      setMessages(msgs)

      // Subscribe to real-time messages
      channelRef.current = subscribeToMessages(convo.id, (newMsg) => {
        setMessages(prev => [...prev, newMsg])
      })
    }
    init()

    return () => {
      if (channelRef.current) unsubscribeFromMessages(channelRef.current)
    }
  }, [contactUsername, session])

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  async function handleSend(isTranscribed = false) {
    if (!input.trim() || !canSend || !conversation) return
    const content = input.trim()
    setInput('')
    try {
      await sendMessage({
        conversationId: conversation.id,
        clientId: session.client.id,
        sentByUserId: session.user.id,
        content,
        isTranscribed
      })
    } catch (e) {
      console.error('Send failed:', e)
    }
  }

  async function handleEdit(id) {
    await editMessage(id, editContent)
    setMessages(prev => prev.map(m => m.id === id ? { ...m, content: editContent, is_edited: true } : m))
    setEditingId(null)
  }

  async function handleDelete(id) {
    await deleteMessage(id)
    setMessages(prev => prev.filter(m => m.id !== id))
  }

  function handleMic() {
    setRecording(r => !r)
    if (recording) {
      // Simulate voice transcription - in production wire up Web Speech API
      setInput('Voice message transcribed here')
    }
  }

  function formatTime(ts) {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  }

  const initials = (str) => str.split(' ').map(w => w[0]).join('').toUpperCase().slice(0,2)

  return (
    <div style={s.wrap}>
      {/* Header */}
      <div style={s.header}>
        <button style={s.backBtn} onClick={() => navigate('/inbox')}>←</button>
        <div style={{ ...s.avatar, background:'#1e2d4a', color:'#378add' }}>
          {initials(contactUsername)}
        </div>
        <div style={s.headerInfo}>
          <div style={s.headerHandle}>@{contactUsername}</div>
          <div style={s.headerStatus}>online · 7am–11pm ET</div>
        </div>
      </div>

      {/* Thread banner */}
      <div style={s.threadBanner}>
        👤 your thread · {session.user.full_name} · relay responses to @{session.client.username}
      </div>

      {/* Messages */}
      <div style={s.messages}>
        {messages.map(msg => {
          const isMine = msg.sender === 'user'
          return (
            <div key={msg.id} style={{ ...s.msgRow, justifyContent: isMine ? 'flex-end' : 'flex-start' }}>
              {!isMine && (
                <div style={{ ...s.msgAvatar, background:'#1e2d4a', color:'#378add' }}>
                  {initials(contactUsername)}
                </div>
              )}
              <div>
                {editingId === msg.id ? (
                  <div style={s.editWrap}>
                    <input
                      style={s.editInput}
                      value={editContent}
                      onChange={e => setEditContent(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleEdit(msg.id)}
                      autoFocus
                    />
                    <button style={s.editSave} onClick={() => handleEdit(msg.id)}>save</button>
                    <button style={s.editCancel} onClick={() => setEditingId(null)}>cancel</button>
                  </div>
                ) : (
                  <div
                    style={{ ...s.bubble, ...(isMine ? s.bubbleMine : s.bubbleTheirs) }}
                    onDoubleClick={() => {
                      if (isMine) { setEditingId(msg.id); setEditContent(msg.content) }
                    }}
                  >
                    {msg.content}
                  </div>
                )}
                <div style={{ ...s.msgTime, textAlign: isMine ? 'right' : 'left' }}>
                  {formatTime(msg.created_at)}
                  {msg.is_edited && <span style={{ color:'#333' }}> · edited</span>}
                  {msg.is_transcribed && <span style={{ color:'#0f6e56' }}> 🎤 transcribed</span>}
                  {isMine && !editingId && (
                    <span>
                      {' '}·{' '}
                      <span style={s.actionLink} onClick={() => { setEditingId(msg.id); setEditContent(msg.content) }}>edit</span>
                      {' '}
                      <span style={{ ...s.actionLink, color:'#e24b4a' }} onClick={() => handleDelete(msg.id)}>delete</span>
                    </span>
                  )}
                </div>
              </div>
              {isMine && (
                <div style={{ ...s.msgAvatar, background:'#1e6a4a', color:'#5dcaa5' }}>JR</div>
              )}
            </div>
          )
        })}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      {canSend && (
        <div style={s.inputRow}>
          <div style={s.inputWrap}>
            <textarea
              style={s.input}
              placeholder="message..."
              value={input}
              rows={1}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend() } }}
            />
            <button style={{ ...s.micBtn, color: recording ? '#e24b4a' : '#555' }} onClick={handleMic}>🎤</button>
          </div>
          <button style={s.sendBtn} onClick={() => handleSend()}>➤</button>
        </div>
      )}
      {!canSend && (
        <div style={s.readOnlyBar}>read only · you cannot send messages</div>
      )}
    </div>
  )
}

